  avaEnv.CLOUDFLARE_ACCOUNT_ID,
  avaEnv.ROOTMC_CLOUDFLARE_ACCOUNT_ID,
  "a1b2c3d4", // will be filtered
].filter((a) => a && String(a).length > 10);

