import { createRequire } from "node:module";
import { loadRootMcEnv } from "../../rootmc-realm-api/scripts/lib/rootmc-env.mjs";

const require = createRequire(
  new URL("../../rootmc-api/package.json", import.meta.url),
);
const mysql = require("mysql2/promise");
const UUID = "3e660994-b16c-4714-bc15-9081aa928729";
const env = loadRootMcEnv();

const candidates = [
  process.env.CLOUDFLARE_HYPERDRIVE_LOCAL_CONNECTION_STRING_ROOTMC_MYSQL,
  env.CLOUDFLARE_HYPERDRIVE_LOCAL_CONNECTION_STRING_ROOTMC_MYSQL,
  env.ROOTMC_MYSQL_URL,
  env.CLAIMS_MYSQL_URL,
  env.MYSQL_URL,
].filter(Boolean);

console.log(
  "conn candidates",
  candidates.map((c) => {
    try {
      const u = new URL(String(c).replace(/^mysql2?:\/\//, "mysql://"));
      return `${u.hostname}:${u.port || 3306}/${u.pathname} user=${u.username}`;
    } catch {
      return "(bad)";
    }
  }),
);

async function open(connStr) {
  const url = new URL(String(connStr).replace(/^mysql2?:\/\//, "mysql://"));
  return mysql.createConnection({
    host: url.hostname,
    port: Number(url.port || 3306),
    user: decodeURIComponent(url.username),
    password: decodeURIComponent(url.password),
    database: url.pathname.replace(/^\//, "").split("?")[0] || undefined,
    connectTimeout: 15000,
  });
}

const connStr = candidates[0];
const conn = await open(connStr);
const [[dbRow]] = await conn.query("SELECT DATABASE() AS db");
const [dbs] = await conn.query("SHOW DATABASES");
console.log("current db", dbRow);
console.log(
  "databases",
  dbs.map((r) => r.Database).filter((n) => !/information|performance|mysql|sys/i.test(n)),
);

for (const db of dbs.map((r) => r.Database)) {
  if (/information|performance|mysql|sys/i.test(db)) continue;
  const [tables] = await conn.query(
    `SELECT TABLE_NAME AS t FROM information_schema.TABLES WHERE TABLE_SCHEMA = ? AND (TABLE_NAME LIKE '%vote%' OR TABLE_NAME LIKE '%shard%' OR TABLE_NAME LIKE '%ender%' OR TABLE_NAME LIKE '%reward%' OR TABLE_NAME LIKE '%appreciation%')`,
    [db],
  );
  if (tables.length) {
    console.log("db", db, "tables", tables.map((x) => x.t));
  }
}

// Prefer claims-ish db
const prefer = ["rootmc", "claims", "root_claims", "shockbyte", dbRow.db].filter(Boolean);
let targetDb = dbRow.db;
for (const p of prefer) {
  const hit = dbs.find((r) => String(r.Database).toLowerCase().includes(String(p).toLowerCase()));
  if (hit) {
    // keep scanning - pick one with vote tables
  }
}

const [voteTables] = await conn.query(
  `SELECT TABLE_SCHEMA AS s, TABLE_NAME AS t FROM information_schema.TABLES
   WHERE TABLE_NAME LIKE '%vote_shard%' OR TABLE_NAME LIKE '%rewards_votes%' OR TABLE_NAME LIKE '%double_ender%'`,
);
console.log("vote-ish tables globally", voteTables);

const results = {};
for (const row of voteTables) {
  const fq = `\`${row.s}\`.\`${row.t}\``;
  try {
    if (/issued/i.test(row.t)) {
      const [r] = await conn.query(`SELECT * FROM ${fq} WHERE player_uuid = ?`, [UUID]);
      results[`issued ${fq}`] = r;
    } else if (/pending/i.test(row.t)) {
      const [open] = await conn.query(
        `SELECT COUNT(*) AS c, COALESCE(SUM(weight),0) AS w FROM ${fq} WHERE player_uuid = ? AND delivered_at IS NULL`,
        [UUID],
      );
      const [all] = await conn.query(
        `SELECT COUNT(*) AS c, COALESCE(SUM(weight),0) AS w FROM ${fq} WHERE player_uuid = ?`,
        [UUID],
      );
      const [sample] = await conn.query(
        `SELECT id, weight, idempotency_key, created_at, delivered_at FROM ${fq} WHERE player_uuid = ? ORDER BY id DESC LIMIT 8`,
        [UUID],
      );
      results[`pending ${fq}`] = { open, all, sample };
    } else if (/rewards_votes/i.test(row.t)) {
      const [cols] = await conn.query(`SHOW COLUMNS FROM ${fq}`);
      const colNames = cols.map((c) => c.Field);
      const uuidCol = colNames.includes("player_uuid")
        ? "player_uuid"
        : colNames.includes("minecraft_uuid")
          ? "minecraft_uuid"
          : null;
      if (uuidCol) {
        const [r] = await conn.query(
          `SELECT COUNT(*) AS c FROM ${fq} WHERE ${uuidCol} = ?`,
          [UUID],
        );
        results[`votes ${fq}`] = { count: r, cols: colNames };
      } else {
        results[`votes ${fq}`] = { cols: colNames, note: "no uuid col" };
      }
    } else if (/double_ender/i.test(row.t)) {
      const [r] = await conn.query(
        `SELECT server_id, minecraft_uuid, minecraft_username, CHAR_LENGTH(contents_b64) AS b64_len, migrated_vanilla, updated_at FROM ${fq} WHERE minecraft_uuid = ?`,
        [UUID],
      );
      results[`ec ${fq}`] = r;
    }
  } catch (e) {
    results[`err ${fq}`] = e.message;
  }
}

await conn.end();
console.log(JSON.stringify(results, null, 2));

