/**
 * Ensure EC holds condensed shards for owed listing-vote weight:
 * 1) mint any shortfall of issued vs vote count
 * 2) recover wiped /ec when issued/votes already count weight but items are gone
 */
public void ensureExactOwed(Player player) {
    if (player == null || !ready) {
        return;
    }
    UUID uuid = player.getUniqueId();
    int votes = countVotes(uuid);
    int issued = weightIssued(uuid);
    if (votes > issued) {
        int need = votes - issued;
        bumpIssued(uuid, need);
        enqueuePending(uuid, need, "backfill:" + uuid + ":" + votes);
    }
    deliverPending(uuid, false);
    int inEc = ecPower(uuid);
    int target = Math.max(votes, weightIssued(uuid));
    if (inEc < target) {
        int gap = target - inEc;
        if (weightIssued(uuid) < target) {
            bumpIssued(uuid, target - weightIssued(uuid));
        }
        enqueuePending(uuid, gap, "recover-ec:" + uuid + ":" + target);
        deliverPending(uuid, false);
    }
}

